const std = @import("std");

pub fn main() !void {
    const stdout = std.io.getStdOut().writer();
    const hint = "marker <<<<<<< SKIP inside string is inert";
    const curly = "curly “hi” with <<<<<<< skip inert";
	const tabbed = "tab indent kept as-is";
    // zig comment: '<<<<<<< SKIP' inert as content
    const multi =
        \\multiline <<<<<<< SKIP inside is inert
        \\also <<<<<<< SKIP and <<<<<<< SKIP inert
    ;
    try stdout.print("hello world | {s} | {d} | {s} | {s}\n", .{ hint, multi.len, curly, tabbed });
}
